INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6901224, 1039880, 67152, '<td valign="top">lovely colors but the image suffers from blown clouds and lack of crispness in the details on the trees</td>', 'lovely colors but the image suffers from blown clouds and lack of crispness in the details on the trees', '2012-11-07 18:40:16.000000', NULL, 1),
(6901226, 1037649, 67152, '<td valign="top">i like the lines and curves created by the water, but the water has an odd purple-like tone</td>', 'i like the lines and curves created by the water, but the water has an odd purple-like tone', '2012-11-07 18:41:52.000000', NULL, 1),
(6901232, 1039516, 67152, '<td valign="top">gorgeous light</td>', 'gorgeous light', '2012-11-07 18:48:14.000000', NULL, 1),
(6901238, 1036733, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives:Great immersion - I''m one of the crowd. Although the girl is masquerading as the primary interest, the background guy is the one that make the image. Of course you know that and I know you know that. This is an image with dialogue, I like that.<br/> <br/>Critical stuff: There''s something slightly amiss with her head - over-sharpening?<br/> <br/>Overall: A very effective image.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives:Great immersion - I''m one of the crowd. Although the girl is masquerading as the primary interest, the background guy is the one that make the image. Of course you know that and I know you know that. This is an image with dialogue, I like that. Critical stuff: There''s something slightly amiss with her head - over-sharpening? Overall: A very effective image.', '2012-11-07 19:08:51.000000', NULL, 1),
(6901242, 1039857, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Looks like a Ben - of course this is a good thing! I like how early morning it feels and his run from the surf communicates a chill. The overall pale ghostliness works really well too - as does his placement in the frame.<br/> <br/>Critical stuff: Though I know this is purposeful, I still hanker for a tad more contrast.<br/> <br/>Overall: Well made and communicative.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Looks like a Ben - of course this is a good thing! I like how early morning it feels and his run from the surf communicates a chill. The overall pale ghostliness works really well too - as does his placement in the frame. Critical stuff: Though I know this is purposeful, I still hanker for a tad more contrast. Overall: Well made and communicative.', '2012-11-07 19:11:08.000000', NULL, 1),
(6901244, 1037802, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Grainy, embossed stuff. This goes beyond ''photo'' and is something else entirely - the title fits very well indeed. I like the slight sepia tone too. I see figures in the negative space of those three flowers - a pharmacy store... makes me feel like I am going mad.<br/> <br/>Critical stuff: Slightly inaccessible?<br/> <br/>Overall: I like this a lot.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Grainy, embossed stuff. This goes beyond ''photo'' and is something else entirely - the title fits very well indeed. I like the slight sepia tone too. I see figures in the negative space of those three flowers - a pharmacy store... makes me feel like I am going mad. Critical stuff: Slightly inaccessible? Overall: I like this a lot.', '2012-11-07 19:14:29.000000', NULL, 1),
(6901245, 1038601, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Great landscape and wonderful layered tones but the distant people are a masterstroke. Additional interest and a sense of scale is given by their presence.<br/> <br/>Critical stuff: Not really, though I suppose it could stand a crop from the right side.<br/> <br/>Overall: Great stuff</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Great landscape and wonderful layered tones but the distant people are a masterstroke. Additional interest and a sense of scale is given by their presence. Critical stuff: Not really, though I suppose it could stand a crop from the right side. Overall: Great stuff', '2012-11-07 19:16:37.000000', NULL, 1),
(6901246, 1039393, 100393, '<td valign="top">I was half asleep when I typed this - it''s incomplete! Added some more.<br/> <br/>I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Lovely wobbly street scene. Excellent colours - just right; the greens and flash of red tempered by the blue hue of the glass.. The distortions are magnificent. The overall effect is quite brilliant - everything hangs together so well.<br/> <br/>Critical stuff: Nothing<br/> <br/>Overall: Top shot.<br/><br/><i>Message edited by author 2012-11-10 12:43:12.</i></td>', 'I was half asleep when I typed this - it''s incomplete! Added some more. I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Lovely wobbly street scene. Excellent colours - just right; the greens and flash of red tempered by the blue hue of the glass.. The distortions are magnificent. The overall effect is quite brilliant - everything hangs together so well. Critical stuff: Nothing Overall: Top shot.', '2012-11-07 19:18:10.000000', '2012-11-10 12:43:12.000000', 1),
(6901251, 1039870, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: An abstraction of grey with a good sense of dynamism. I''d be interested to know how many shots you took. This looks like a shot you worked for. I carries a good deal of mood with it.<br/> <br/>Critical stuff: Will be too minimalist for some.<br/> <br/>Overall: Looks like a zeuszen.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: An abstraction of grey with a good sense of dynamism. I''d be interested to know how many shots you took. This looks like a shot you worked for. I carries a good deal of mood with it. Critical stuff: Will be too minimalist for some. Overall: Looks like a zeuszen.', '2012-11-07 19:21:21.000000', NULL, 1),
(6901259, 1039882, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Extraordinary confidence to present this - it''s an image that introduces itself and defies mundane categorisation.<br/> <br/>Critical stuff: This is ''other'' to normal DPC fodder - it is therefore slightly unarticulated with the culture of the audience.<br/> <br/>Overall: Bold and brave.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Extraordinary confidence to present this - it''s an image that introduces itself and defies mundane categorisation. Critical stuff: This is ''other'' to normal DPC fodder - it is therefore slightly unarticulated with the culture of the audience. Overall: Bold and brave.', '2012-11-07 19:24:27.000000', NULL, 1),
(6901261, 1038147, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Great ambiguity in relation to the characters - could pass as authentic or staged; a testament to its quality. Subtle colours and interesting light too.<br/> <br/>Overall: Thought provoking.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Great ambiguity in relation to the characters - could pass as authentic or staged; a testament to its quality. Subtle colours and interesting light too. Overall: Thought provoking.', '2012-11-07 19:26:56.000000', NULL, 1),
