(6901676, 1039873, 108580, '<td valign="top">Underappreciated. I agree with Neil''s assessment however it still garnered a 7 from me. Perhaps not a boat but a different angle. You might also need to work on the SFW workflow and sharpening?</td>', 'Underappreciated. I agree with Neil''s assessment however it still garnered a 7 from me. Perhaps not a boat but a different angle. You might also need to work on the SFW workflow and sharpening?', '2012-11-08 01:38:50.000000', NULL, 0),
(6901679, 1039802, 108580, '<td valign="top">Enjoyed this enough and gave it a 7 Amanda. I think the central-ness of the tree might have have let it down compositionally for the majority of voters.</td>', 'Enjoyed this enough and gave it a 7 Amanda. I think the central-ness of the tree might have have let it down compositionally for the majority of voters.', '2012-11-08 01:41:28.000000', NULL, 0),
