INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6902399, 1039821, 138630, '<td valign="top">FINE shot.  I gave you an 8 but it would have been a 9 or 10 had I ever suspected this had been shot in the wild.  We have them in our zoo and I once had an opportunity to photograph one free in the aviary there, on the railing of the walkway and quite unafraid.  Even had time to change lenses and could probably have touched it.  So, though this is better than any of mine, I wasn''t as impressed as I might have been.  I''m really sorry as your image is first rate.</td>', 'FINE shot.  I gave you an 8 but it would have been a 9 or 10 had I ever suspected this had been shot in the wild.  We have them in our zoo and I once had an opportunity to photograph one free in the aviary there, on the railing of the walkway and quite unafraid.  Even had time to change lenses and could probably have touched it.  So, though this is better than any of mine, I wasn''t as impressed as I might have been.  I''m really sorry as your image is first rate.', '2012-11-08 19:58:39.000000', NULL, 0),
(6902404, 1038654, 138630, '<td valign="top">No time to comment on all the ones that struck my fancy but this was one of them, Anita.  Love how it shimmers.</td>', 'No time to comment on all the ones that struck my fancy but this was one of them, Anita.  Love how it shimmers.', '2012-11-08 20:03:14.000000', NULL, 0),
(6902405, 1039516, 138630, '<td valign="top">8 from me - surprised me, too, by its relatively low finish.  I think it may be what''s called the speed voters.  It really has to be paused over and studied to be fully appreciated.  I bumped and bumped :)</td>', '8 from me - surprised me, too, by its relatively low finish.  I think it may be what''s called the speed voters.  It really has to be paused over and studied to be fully appreciated.  I bumped and bumped :)', '2012-11-08 20:06:43.000000', NULL, 0),
(6902406, 1036914, 138630, '<td valign="top">Gave this an 8 - it''s gorgeous.  Couldn''t figure out the clouds vs the foreground.  Just now realized that the foreground is ice or snow and not foam-capped, moving water . . .</td>', 'Gave this an 8 - it''s gorgeous.  Couldn''t figure out the clouds vs the foreground.  Just now realized that the foreground is ice or snow and not foam-capped, moving water . . .', '2012-11-08 20:09:42.000000', NULL, 0),
(6902408, 1039785, 30214, '<td valign="top">beautiful shot, congratulations on the ribbon!</td>', 'beautiful shot, congratulations on the ribbon!', '2012-11-08 20:13:15.000000', NULL, 0),
(6902412, 1037649, 67152, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by robgregory:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by bassbone:</b></div><hr/><i> i like the lines and curves created by the water, but the water has an odd purple-like tone </i></td></tr></table> <br/> <br/>Yeah, the reflection of the red trees on the wet black rocks created kind of a purplish effect, but that was one of the things I liked about it!<br/> <br/>Thanks for the comment! </i></td></tr></table> <br/>My guess is that you oversaturated your blues a bit while you were boosting the saturation on the rest of the image.  If you pull back the saturation on the Blue channel about -25, the image would not have had the purplish tint.</td>', 'Originally posted by robgregory: Originally posted by bassbone: i like the lines and curves created by the water, but the water has an odd purple-like tone   Yeah, the reflection of the red trees on the wet black rocks created kind of a purplish effect, but that was one of the things I liked about it! Thanks for the comment!  My guess is that you oversaturated your blues a bit while you were boosting the saturation on the rest of the image.  If you pull back the saturation on the Blue channel about -25, the image would not have had the purplish tint.', '2012-11-08 20:20:00.000000', NULL, 0),
(6902449, 1039850, 93565, '<td valign="top">I gotta agree about the border, Michelle. I''m usually kinda in the middle for them, some photos are better, some not, but it seems a bit strong.<br/> <br/>But that''s pretty minor.<br/>This is a gorgeous conversion and the scene is just great. Very fantasy inducing, the proverbial mysterious forest. Wonderful light and I really like the way the leaf detail is rendered. It''s not quite sharp but somewhat "flowy," which only adds to the effect I was mentioning earlier.<br/>Great job here.</td>', 'I gotta agree about the border, Michelle. I''m usually kinda in the middle for them, some photos are better, some not, but it seems a bit strong. But that''s pretty minor.This is a gorgeous conversion and the scene is just great. Very fantasy inducing, the proverbial mysterious forest. Wonderful light and I really like the way the leaf detail is rendered. It''s not quite sharp but somewhat "flowy," which only adds to the effect I was mentioning earlier.Great job here.', '2012-11-08 21:00:25.000000', NULL, 0),
(6902467, 1038147, 68504, '<td valign="top">so much we don''t know, but let us gorge on appearances.</td>', 'so much we don''t know, but let us gorge on appearances.', '2012-11-08 21:17:08.000000', NULL, 0),
(6902479, 1038668, 42013, '<td valign="top">Nice one Mark -- clearly the top image in this FS. Congrats!</td>', 'Nice one Mark -- clearly the top image in this FS. Congrats!', '2012-11-08 21:37:13.000000', NULL, 0),
(6902480, 1038784, 42013, '<td valign="top">Congrats Dennis -- very cool night shot and looks great next to the Icelandic version of night!</td>', 'Congrats Dennis -- very cool night shot and looks great next to the Icelandic version of night!', '2012-11-08 21:37:56.000000', NULL, 0),
